<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import EditorChoice from './EditorChoice.vue';
import {playbackEngineApi} from '@/services/api';
import type {PlaybackEngineAdmin,PlaybackEngineConfig} from '@/services/api';
import type {Platform} from '@/domain/types';
const emit=defineEmits<{(e:'dirty',value:boolean):void}>();
const data=ref<PlaybackEngineAdmin|null>(null),draft=ref<PlaybackEngineConfig>({profiles:[]});
const selected=ref<Platform>('mobile'),os=ref('android');
const loading=ref(true),busy=ref(false),error=ref(''),message=ref(''),manifestOpen=ref(false),manifestText=ref('');
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value));
const clients:{id:Platform;label:string;detail:string}[]=[{id:'mobile',label:'手机客户端',detail:'Android · iOS'},{id:'tablet',label:'平板客户端',detail:'Android · iPadOS'},{id:'tv',label:'电视客户端',detail:'Android TV'},{id:'web',label:'电脑客户端',detail:'Windows · 浏览器'}];
const systems=computed(()=>data.value?.targets.filter(t=>t.platform===selected.value).map(t=>({id:t.os,label:t.label}))||[]);
const profile=computed(()=>draft.value.profiles.find(p=>p.platform===selected.value&&p.os===os.value));
const published=computed(()=>data.value?.settings.published.profiles.find(p=>p.platform===selected.value&&p.os===os.value));
const dirty=computed(()=>!!data.value&&JSON.stringify(draft.value)!==JSON.stringify(data.value.settings.draft));
const unpublished=computed(()=>!!data.value&&JSON.stringify(draft.value)!==JSON.stringify(data.value.settings.published));
const disabled=computed(()=>loading.value||busy.value);
const choices=computed(()=>[{id:'',label:'请选择主内核'},...(data.value?.engines.filter(e=>e.systems.includes(os.value)).map(e=>({id:e.id,label:e.name+(profile.value?.build?.engines.some(i=>i.id===e.id)?' · 已声明':' · 待接入')}))||[])]);
const backupChoices=computed(()=>[{id:'',label:'不使用备用内核'},...choices.value.filter(e=>e.id&&e.id!==profile.value?.primary)]);
const registered=computed(()=>profile.value?.build?.engines.map(e=>({ ...e,name:data.value?.engines.find(d=>d.id===e.id)?.name||e.id }))||[]);
const latestReport=computed(()=>data.value?.settings.observations.find(r=>r.platform===selected.value&&r.os===os.value&&r.appId===profile.value?.build?.appId&&r.appVersion===profile.value?.build?.appVersion));
const reportFresh=computed(()=>!!latestReport.value&&Date.now()-Date.parse(latestReport.value.at)<24*3600*1000&&latestReport.value.policyVersion===data.value?.settings.publishedVersion);
const licenseLabels:Record<string,string>={not_required:'无需商业授权',unknown:'授权未确认',valid:'声明授权有效',invalid:'声明授权无效'};
const conditions=[{id:'initialization',label:'内核初始化失败'},{id:'decode',label:'媒体解码失败'},{id:'stall',label:'持续卡顿超时'}];
const reasons:Record<string,string>={initialization:'内核初始化失败',decode:'媒体解码失败',stall:'持续卡顿',network:'资源或网络错误',license:'SDK 授权错误',other:'其他播放错误'};
watch(dirty,v=>emit('dirty',v),{immediate:true});
watch(()=>profile.value?.primary,()=>{if(profile.value&&profile.value.primary===profile.value.backup)profile.value.backup='';});
function receive(v:PlaybackEngineAdmin){data.value=v;draft.value=clone(v.settings.draft);}
function chooseClient(p:Platform){selected.value=p;os.value=data.value?.targets.find(t=>t.platform===p)?.os||'android';manifestText.value='';manifestOpen.value=false;error.value='';message.value='';}
function chooseOS(value:string){os.value=value;manifestText.value='';manifestOpen.value=false;error.value='';message.value='';}
const changed=(e:Event)=>!!(e as Event & {detail:{value:boolean}}).detail.value;
function toggleCondition(id:string){if(!profile.value)return;profile.value.switchOn=profile.value.switchOn.includes(id)?profile.value.switchOn.filter(v=>v!==id):[...profile.value.switchOn,id];}
async function load(){loading.value=true;error.value='';try{receive(await playbackEngineApi.get());}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
function reload(){if(!dirty.value){void load();return;}uni.showModal({title:'重新加载内核配置',content:'当前有未保存的内核设置，重新加载会放弃修改。',success:r=>{if(r.confirm)void load();}});}
async function save(){if(!data.value)return;busy.value=true;error.value='';message.value='';try{receive(await playbackEngineApi.save(data.value.settings.revision,clone(draft.value)));message.value='内核草稿已保存；发布后客户端才能读取。';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function publish(){if(!data.value)return;busy.value=true;error.value='';message.value='';try{if(dirty.value)receive(await playbackEngineApi.save(data.value.settings.revision,clone(draft.value)));receive(await playbackEngineApi.publish(data.value.settings.revision));message.value='内核策略已发布。客户端需通过能力协商后执行。';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function inspect(){if(!profile.value)return;busy.value=true;error.value='';message.value='';try{let raw:unknown;try{raw=JSON.parse(manifestText.value);}catch{throw Error('能力声明不是有效 JSON，请检查文件内容。');}const checked=await playbackEngineApi.inspect(raw);if(checked.build.platform!==selected.value||checked.build.os!==os.value)throw Error('能力声明不属于当前客户端和系统，请切换到对应位置导入。');profile.value.build=clone(checked.build);manifestOpen.value=false;manifestText.value='';message.value='基础包能力已加入当前草稿。这是能力声明，实际播放状态由客户端反馈。';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function clearBuild(){uni.showModal({title:'移除基础包能力',content:'移除当前草稿中的能力声明，并关闭该系统策略。发布后生效。',success:r=>{if(r.confirm&&profile.value){profile.value.build=null;profile.value.enabled=false;}}});}
const buildExample=computed(()=>JSON.stringify({contract:'hetun-playback-build-v1',platform:selected.value,os:os.value,appId:'应用实际包名或 Bundle ID',appVersion:'实际三段版本号',engines:[{id:os.value==='ios'?'avplayer':os.value==='windows'?'libvlc':os.value==='web'?'html5':'android-system',version:'实际 SDK 版本',license:'not_required'}],features:['engine-policy','playback-report','resume-position']},null,2));
function copyFormat(){uni.setClipboardData({data:buildExample.value});}
function formatTime(value:string){return new Date(value).toLocaleString();}
onMounted(load);
</script>

<template>
<view class="engine-panel">
 <view class="engine-heading"><view><text class="engine-kicker">PLAYER ENGINE</text><text class="engine-title">播放内核管理</text><text class="engine-subtitle">一个 CMS · 一个运营中心 · 四端按系统配置</text></view><view class="engine-actions"><button :disabled="disabled" @click="reload">重新加载</button><button :disabled="disabled||!dirty" @click="save">保存内核草稿</button><button class="engine-primary" :disabled="disabled||!data||(!unpublished&&!dirty&&data.settings.publishedVersion>0)" @click="publish">{{busy?'处理中…':'发布内核策略'}}</button></view></view>
 <view v-if="error" class="engine-feedback engine-error" role="alert">{{error}}</view><view v-if="message" class="engine-feedback" role="status">{{message}}</view>
 <view v-if="loading" class="engine-empty">正在读取内核配置…</view>
 <template v-else-if="data">
 <view class="engine-tabs" role="tablist" aria-label="内核客户端"><button v-for="client in clients" :key="client.id" :disabled="disabled" :class="{selected:selected===client.id}" :aria-selected="selected===client.id" role="tab" @click="chooseClient(client.id)"><text>{{client.label}}</text><text class="engine-tab-detail">{{client.detail}}</text></button></view>
 <view v-if="profile" class="engine-editor">
  <view class="engine-target"><view class="engine-system"><text>目标系统</text><EditorChoice :model-value="os" :options="systems" :disabled="disabled" @update:model-value="chooseOS"/></view><view class="engine-enable"><text>启用该系统策略</text><switch :checked="profile.enabled" :disabled="disabled" @change="profile.enabled=changed($event)" aria-label="启用当前系统内核策略"/></view></view>
  <view class="engine-status-grid"><view><text class="engine-status-label">基础包能力</text><strong>{{profile.build?'已登记声明':'尚未登记'}}</strong><text class="engine-hint">{{profile.build?profile.build.appId+' · v'+profile.build.appVersion:'需先集成 SDK 及客户端策略适配器'}}</text></view><view><text class="engine-status-label">客户端播放反馈</text><strong :class="{'engine-warning':latestReport?.outcome==='failed'}">{{!latestReport?'未检测':!reportFresh?'历史反馈':latestReport.outcome==='prepared'?'客户端报告已就绪':'最近播放失败'}}</strong><text class="engine-hint">{{latestReport?formatTime(latestReport.at)+(latestReport.reason?' · '+reasons[latestReport.reason]:''):'尚未收到已授权播放签发的反馈'}}</text></view><view><text class="engine-status-label">发布状态</text><strong>{{JSON.stringify(profile)!==JSON.stringify(published)?'有待发布修改':data.settings.publishedVersion?'已同步 v'+data.settings.publishedVersion:'尚未发布'}}</strong><text class="engine-hint">{{data.settings.publishedAt?formatTime(data.settings.publishedAt):'保存草稿后，校验能力并发布'}}</text></view></view>
  <view class="engine-fields"><label>主播放内核<EditorChoice v-model="profile.primary" :options="choices" :disabled="disabled"/></label><label>备用播放内核<EditorChoice v-model="profile.backup" :options="backupChoices" :disabled="disabled"/></label></view>
  <view class="engine-options"><view><text>允许用户手动切换</text><switch :checked="profile.manualSwitch" :disabled="disabled" @change="profile.manualSwitch=changed($event)" aria-label="允许手动切换内核"/></view><view><text>内核故障自动切换</text><switch :checked="profile.autoSwitch" :disabled="disabled" @change="profile.autoSwitch=changed($event)" aria-label="内核故障自动切换"/></view><view><text>切换后恢复播放进度</text><switch :checked="profile.resumePosition" :disabled="disabled" @change="profile.resumePosition=changed($event)" aria-label="切换恢复播放进度"/></view></view>
  <view class="engine-conditions"><text>自动切换条件</text><view><button v-for="condition in conditions" :key="condition.id" :disabled="disabled||!profile.autoSwitch" :class="{chosen:profile.switchOn.includes(condition.id)}" :aria-pressed="profile.switchOn.includes(condition.id)" @click="toggleCondition(condition.id)">{{condition.label}}</button></view><text class="engine-hint">地址失效、解析失败由下方解析调度处理；内核故障使用这里的切换规则。</text></view>
  <view class="engine-budget"><label>单次播放最多切换内核<input v-model.number="profile.maxSwitches" type="number" min="0" max="2" :disabled="disabled"/></label><label>来源与内核组合尝试上限<input v-model.number="profile.maxAttempts" type="number" min="1" max="20" :disabled="disabled"/></label><label>播放恢复总时限（秒）<input v-model.number="profile.sessionSeconds" type="number" min="15" max="300" :disabled="disabled"/></label></view>
  <view class="engine-capability"><view class="engine-capability-heading"><view><text class="engine-section-title">基础包与授权</text><text class="engine-hint">登记实际集成清单；发布和客户端协商都会校验内核、应用版本与执行能力。</text></view><view class="engine-actions"><button :disabled="disabled" @click="manifestOpen=!manifestOpen">{{manifestOpen?'收起':'登记基础包能力'}}</button><button v-if="profile.build" class="engine-danger" :disabled="disabled" @click="clearBuild">移除声明</button></view></view>
   <view v-if="registered.length" class="engine-installed"><view v-for="engine in registered" :key="engine.id"><text>{{engine.name}} <text class="engine-hint">{{engine.version}}</text></text><text :class="{'engine-warning':engine.license==='unknown'||engine.license==='invalid'}">{{licenseLabels[engine.license]}}</text></view><text class="engine-hint">上方为基础包声明。商业授权由客户端 SDK 校验，后台登记不代替服务商授权。</text></view>
   <view v-else class="engine-no-build">尚未登记基础包；可先保存设计草稿，启用策略需完成能力校验。</view>
   <view v-if="manifestOpen" class="engine-manifest"><view class="engine-capability-heading"><text class="engine-hint">粘贴开发或打包流程提供的 hetun-playback-build-v1 JSON 能力文件。</text><button :disabled="disabled" @click="copyFormat">复制接入格式</button></view><textarea v-model="manifestText" :disabled="disabled" :maxlength="32768" placeholder="粘贴实际基础包能力 JSON" aria-label="基础包能力声明 JSON"/><button class="engine-primary" :disabled="disabled||!manifestText.trim()" @click="inspect">校验并加入草稿</button></view>
  </view>
  <view class="engine-footer"><text>未登记的内核显示“待接入”；只有安装包声明且客户端实际具备的内核才会参与协商。旧版客户端继续使用自身播放器。</text><text>内核草稿修订 {{data.settings.revision}} · 解析配置与内核策略分别发布</text></view>
 </view>
 </template>
</view>
</template>

<style scoped>
.engine-panel{padding:24px;border:1px solid #80808025;border-radius:15px;background:#80808005;display:flex;flex-direction:column;gap:20px}.engine-heading,.engine-capability-heading{display:flex;align-items:center;justify-content:space-between;gap:18px}.engine-heading>view:first-child,.engine-capability-heading>view:first-child{display:flex;flex-direction:column;gap:7px}.engine-kicker{font-size:10px;letter-spacing:1.8px;opacity:.5}.engine-title{font-size:20px;font-weight:650}.engine-subtitle,.engine-hint{font-size:12px;line-height:1.8;opacity:.65;overflow-wrap:anywhere}.engine-actions{display:flex;gap:9px;align-items:center;flex-shrink:0}button{margin:0;font-size:12px;line-height:2.8;padding:0 14px;border:1px solid #80808035;border-radius:8px;background:transparent;color:inherit}button::after{border:0}button[disabled]{opacity:.42}.engine-primary{background:#e5eddf;color:#35533a;border-color:#d5e2cb;font-weight:600}.engine-tabs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.engine-tabs button{text-align:left;padding:12px 15px;line-height:1.6;display:flex;flex-direction:column;gap:4px}.engine-tabs .selected{background:#b1c5a522;border-color:#89a17a}.engine-tab-detail{font-size:10px;opacity:.55}.engine-editor{display:flex;flex-direction:column;gap:20px}.engine-target{display:flex;justify-content:space-between;align-items:center;gap:20px}.engine-system{display:grid;grid-template-columns:auto minmax(180px,260px);align-items:center;gap:16px;font-size:12px}.engine-enable{display:flex;gap:16px;align-items:center;font-size:12px}.engine-status-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border:1px solid #80808025;border-radius:10px;overflow:hidden}.engine-status-grid>view{display:flex;flex-direction:column;gap:8px;padding:16px;border-right:1px solid #80808020;min-width:0}.engine-status-grid>view:last-child{border-right:0}.engine-status-label{font-size:11px;opacity:.6}.engine-status-grid strong{font-size:15px;font-weight:600}.engine-fields{display:grid;grid-template-columns:1fr 1fr;gap:20px}label{display:flex;flex-direction:column;gap:10px;font-size:12px;min-width:0}.engine-options{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;padding:17px 0;border-top:1px solid #80808020;border-bottom:1px solid #80808020}.engine-options>view{display:flex;gap:10px;justify-content:space-between;align-items:center;font-size:12px}.engine-conditions{display:flex;flex-direction:column;gap:10px;font-size:12px}.engine-conditions>view{display:flex;flex-wrap:wrap;gap:10px}.chosen{background:#b1c5a52b;border-color:#86a677}.engine-budget{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}input{height:42px;padding:0 12px;border:1px solid #80808035;border-radius:8px;background:#80808007;color:inherit;box-sizing:border-box;font-size:13px;min-width:0}.engine-capability{padding:18px;background:#80808005;border:1px solid #80808025;border-radius:10px}.engine-section-title{font-size:14px;font-weight:600;display:block}.engine-installed{display:flex;flex-direction:column;gap:10px;margin-top:16px;font-size:12px}.engine-installed>view{display:flex;gap:20px;justify-content:space-between;padding:10px 0;border-top:1px solid #80808020}.engine-no-build{font-size:12px;opacity:.6;padding-top:15px;line-height:1.8}.engine-manifest{display:flex;flex-direction:column;gap:14px;margin-top:18px}.engine-manifest textarea{width:100%;height:220px;box-sizing:border-box;padding:14px;border:1px solid #80808035;border-radius:9px;background:#80808009;color:inherit;font-size:12px;font-family:monospace}.engine-manifest>button{align-self:flex-end}.engine-footer{display:flex;flex-direction:column;gap:5px;font-size:11px;opacity:.6;line-height:1.9}.engine-feedback{padding:12px 16px;border-radius:8px;font-size:12px;background:#a6bd8e25}.engine-error{color:#c66c6c;background:#d7777720}.engine-warning,.engine-danger{color:#bc815b}.engine-empty{text-align:center;padding:30px;font-size:13px;opacity:.6}@media(max-width:1150px){.engine-heading,.engine-capability-heading{align-items:flex-start;flex-direction:column}.engine-options{grid-template-columns:1fr}.engine-system{grid-template-columns:1fr;gap:8px}.engine-status-grid{grid-template-columns:1fr}.engine-status-grid>view{border-right:0;border-bottom:1px solid #80808020}.engine-status-grid>view:last-child{border-bottom:0}.engine-tabs{grid-template-columns:repeat(2,1fr)}.engine-budget,.engine-fields{grid-template-columns:1fr}.engine-actions{flex-wrap:wrap}.engine-target{align-items:flex-start}}
</style>
